def heads(outcome):
    return outcome.count('H')   # X: a rule, not a mystery

print(heads('HT'))   # 1

outcomes = {'HH': 0.25, 'HT': 0.25, 'TH': 0.25, 'TT': 0.25}

def heads(outcome):
    return outcome.count('H')   # the random variable X
for o in outcomes:
    print(o, heads(o))
# HH 2 / HT 1 / TH 1 / TT 0

outcomes = {'HH': 0.25, 'HT': 0.25, 'TH': 0.25, 'TT': 0.25}

def heads(outcome):
    return outcome.count('H')   # the random variable X
print(sorted({heads(o) for o in outcomes}))   # [0, 1, 2]

outcomes = {'HH': 0.25, 'HT': 0.25, 'TH': 0.25, 'TT': 0.25}

def heads(outcome):
    return outcome.count('H')   # the random variable X
dist = {}
for o, p in outcomes.items():
    dist[heads(o)] = dist.get(heads(o), 0) + p
print(dict(sorted(dist.items())))   # {0: 0.25, 1: 0.5, 2: 0.25}
